mapper.select:
  SELECT COUNT(1)
  FROM time_slots
  WHERE assignment_id = #{assignmentId}
  AND venue_id = #{venueId}

AND NOT (end_at <= #{endAt} OR start_at >= #{startAt})



AND slot_id <> #{excludeSlotId}

SELECT *
FROM time_slots
WHERE assignment_id = #{assignmentId}

    AND slot_date = #{date}


    AND status = #{status}

ORDER BY start_at ASC

SELECT COALESCE(SUM(ts.session_count), 0)
FROM time_slots ts
         JOIN time_slot_examiners tse ON tse.slot_id = ts.slot_id
WHERE ts.assignment_id = #{assignmentId}
  AND tse.examiner_id = #{examinerId}

SELECT *
FROM time_slots
WHERE assignment_id = #{assignmentId}
  AND slot_date >= #{startDate}
  AND slot_date <= #{endDate}
ORDER BY slot_date ASC, start_at ASC
